const weekRange=()=>{const d=new Date(today()+"T12:00:00Z");d.setUTCDate(d.getUTCDate()-((d.getUTCDay()-6+7)%7));const e=new Date(d);e.setUTCDate(e.getUTCDate()+6);return {startDate:d.toISOString().slice(0,10),endDate:e.toISOString().slice(0,10)};};
const seed=()=>({hobbies:[],sessions:[]});
function Btn({children,onClick,primary=false,disabled=false,type}){return <button type={type} disabled={disabled} onClick={onClick} style={{border:"1px solid "+(primary?C.accent:C.line),background:primary?C.accent:"#fff",color:primary?"#fff":C.ink,borderRadius:10,padding:"9px 13px",font:"inherit",fontSize:12,fontWeight:750,cursor:"pointer",opacity:disabled?.55:1}}>{children}</button>}
function Field({label,value,onChange,type="text",required=false,placeholder=""}){return <label style={{display:"grid",gap:5,fontSize:12,color:C.muted}}>{label}<input type={type} value={value??""} onChange={e=>onChange(e.target.value)} required={required} placeholder={placeholder} style={{padding:"10px 11px",border:"1px solid "+C.line,borderRadius:9,font:"inherit",minWidth:0}}/></label>}
function Panel({title,children,action}){return <section style={{background:C.white,border:"1px solid "+C.line,borderRadius:15,padding:16,marginBottom:14}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:10,marginBottom:12}}><b style={{fontSize:15}}>{title}</b>{action}</div>{children}</section>}
